9	pub fn package_paths(pkg: &Package) -> Vec<PathBuf> {
10	    let mut set = std::collections::BTreeSet::new();
11	    for m in &pkg.manifests {
12	        if let Some(parent) = m.path.parent() {
13	            if parent.as_os_str().is_empty() {
14	                set.insert(PathBuf::from("."));
15	            } else {
16	                set.insert(parent.to_path_buf());
17	            }
18	        }
