23	pub fn changed_since_last_tag<R: CommandRunner>(
24	    runner: &R,
25	    root: &Path,
26	    pkg: &Package,
27	    tags: &TagIndex,
28	    git: &GitAccess<'_>,
29	) -> Result<bool, GraphError> {
30	    let Some(last) = tags.last_tag(&pkg.id) else {
31	        return Ok(true);
32	    };
33	
34	    // `git` is a single `GitAccess` built once by the caller and shared
35	    // across every package -- rediscovering it per package (native gix
36	    // repository-open, or a fresh `ShellGit` on the fallback path) for an
37	    // N-package workspace was N redundant discoveries of the exact same
38	    // repository. A failure on either backend is not fatal -- it just means
39	    // the cheap short-circuit below is skipped in favor of the exact `git
40	    // diff --quiet` check.
41	    //
42	    // `last.name` is a tag read back from the repository's own tag list
43	    // (via `TagIndex`), not text Callisto renders itself -- unlike a
44	    // `tag-template`-rendered name, it is not run through
45	    // `is_valid_git_ref_name`. It is fully qualified as `refs/tags/<name>`
46	    // before being shelled to `git log`/`git diff` so it can never be
47	    // misread as a CLI flag by either command's argument parser, even in
48	    // the (currently unreachable, given `TagTemplate::parse`'s and
49	    // `PackageId::parse`'s own leading-hyphen rejections) case of a
50	    // hyphen-leading tag reaching this far.
51	    let qualified = format!("refs/tags/{}", last.name.as_str());
52	
53	    if let Ok(commits) = git.commits_since(Some(&qualified), &[]) {
54	        if !commits.is_empty() {
55	            return Ok(true);
56	        }
57	    }
58	
59	    let paths = package_paths(pkg);
60	    let mut args = vec!["diff", "--quiet", qualified.as_str(), "--"];
61	    let path_strs: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
62	    for p in &path_strs {
63	        args.push(p);
64	    }
